	/// <summary>
	/// Visit a parse tree produced by <see cref="SpekParser.programDecl"/>.
	/// <para>
	/// The default implementation returns the result of calling <see cref="AbstractParseTreeVisitor{Result}.VisitChildren(IRuleNode)"/>
	/// on <paramref name="context"/>.
	/// </para>
	/// </summary>
	/// <param name="context">The parse tree.</param>
	/// <return>The visitor result.</return>
	public virtual Result VisitProgramDecl([NotNull] SpekParser.ProgramDeclContext context) { return VisitChildren(context); }
}
} // namespace Spek.Compiler.Grammar
